            (["PetitionForReadmissionGrantedDat", "PetitionForReAdmitGrantedDate"], {"A": "ceds_ext.FactK12StudentDisciplines_WaExt.PetitionForReadmissionGrantedDate", "BC": "{T}.petition_for_readmission_granted_date"}),
